// Lesson 02: your first circuit.
// An external LED on the breadboard, controlled by typing commands in the serial monitor.
//
//   GPIO 4 ──[ 220-330 Ω ]──►|── GND
//                          long  short
//                          leg   leg
//
// New ideas in this lesson:
//   - PWM (LEDC): blinking a pin thousands of times per second to fake "half brightness".
//   - A non-blocking state machine: the LED keeps animating while we listen for commands.
//
// Commands (type in the monitor, press Enter):
//   on | off | blink [ms] | fade | sos | level <0-255> | help
#include <Arduino.h>
#include <driver/gpio.h>

#include "pins.h"

namespace {

constexpr uint32_t kPwmHz = 5000;   // Fast enough that the eye can't see the flicker.
constexpr uint8_t kPwmBits = 8;     // 8 bits -> duty from 0 (off) to 255 (fully on).
constexpr uint8_t kMaxDuty = 255;

enum class Mode { Off, On, Blink, Fade, Sos };

struct State {
  Mode mode = Mode::Fade;
  uint8_t level = kMaxDuty;    // Brightness used by "on" and "blink".
  uint32_t blinkMs = 500;      // Half-period of "blink".
  uint32_t modeStartedAt = 0;  // millis() when the current mode began.
} state;

const char *modeName(Mode m) {
  switch (m) {
    case Mode::Off: return "off";
    case Mode::On: return "on";
    case Mode::Blink: return "blink";
    case Mode::Fade: return "fade";
    case Mode::Sos: return "sos";
  }
  return "?";
}

// Our eyes see brightness logarithmically: duty 128 looks much brighter than "half".
// Squaring the value (gamma ~2) makes fades look smooth and even.
uint8_t perceived(uint8_t x) { return static_cast<uint16_t>(x) * x / kMaxDuty; }

void setMode(Mode m) {
  state.mode = m;
  state.modeStartedAt = millis();
  log_i("mode -> %s", modeName(m));
}

void printHelp() {
  Serial.println();
  Serial.println("Commands: on | off | blink [ms] | fade | sos | level <0-255> | help");
  Serial.printf("Now: mode=%s level=%u blink=%lums\n", modeName(state.mode), state.level,
                static_cast<unsigned long>(state.blinkMs));
}

// ---- Output: what the LED should show right now, for each mode ----------------------------

// Morse "SOS": ... --- ...   (1 = LED on for one 150 ms unit, 0 = off)
constexpr char kSos[] = "101010001110111011100010101000000";
constexpr uint32_t kSosUnitMs = 150;

uint8_t dutyFor(uint32_t elapsed) {
  switch (state.mode) {
    case Mode::Off:
      return 0;
    case Mode::On:
      return state.level;
    case Mode::Blink:
      return (elapsed / state.blinkMs) % 2 == 0 ? state.level : 0;
    case Mode::Fade: {
      // A triangle wave 0 -> 255 -> 0 every 2 seconds.
      uint32_t t = elapsed % 2000;
      uint8_t x = t < 1000 ? t * kMaxDuty / 1000 : (2000 - t) * kMaxDuty / 1000;
      return perceived(x);
    }
    case Mode::Sos: {
      size_t i = (elapsed / kSosUnitMs) % (sizeof(kSos) - 1);
      return kSos[i] == '1' ? state.level : 0;
    }
  }
  return 0;
}

// ---- Input: read one line from the serial monitor without blocking ------------------------

void handleCommand(String line) {
  line.trim();
  line.toLowerCase();
  if (line.isEmpty()) return;

  int space = line.indexOf(' ');
  String cmd = space < 0 ? line : line.substring(0, space);
  String arg = space < 0 ? "" : line.substring(space + 1);

  if (cmd == "on") {
    setMode(Mode::On);
  } else if (cmd == "off") {
    setMode(Mode::Off);
  } else if (cmd == "fade") {
    setMode(Mode::Fade);
  } else if (cmd == "sos") {
    setMode(Mode::Sos);
  } else if (cmd == "blink") {
    if (!arg.isEmpty()) {
      long ms = arg.toInt();
      if (ms < 20 || ms > 5000) {
        log_w("blink speed must be 20-5000 ms, got '%s'", arg.c_str());
        return;
      }
      state.blinkMs = ms;
    }
    setMode(Mode::Blink);
  } else if (cmd == "level") {
    long v = arg.toInt();
    if (arg.isEmpty() || v < 0 || v > kMaxDuty) {
      log_w("level needs a number 0-255, got '%s'", arg.c_str());
      return;
    }
    state.level = v;
    log_i("level -> %ld", v);
  } else if (cmd == "help" || cmd == "?") {
    printHelp();
  } else {
    log_w("unknown command '%s' (type help)", cmd.c_str());
  }
}

void pollSerial() {
  static String buffer;
  while (Serial.available()) {
    char c = Serial.read();
    if (c == '\n' || c == '\r') {
      handleCommand(buffer);
      buffer = "";
    } else if (buffer.length() < 32) {
      buffer += c;
    }
  }
}

}  // namespace

void setup() {
  Serial.begin(115200);
  delay(1500);

  // Hand the pin to the PWM peripheral. Returns false if the pin can't do PWM.
  if (!ledcAttach(PIN_LED, kPwmHz, kPwmBits)) {
    log_e("Could not attach PWM to GPIO %d. Is it a valid output pin?", PIN_LED);
    return;
  }
  // Safety net: the weakest pin drive (~5 mA) protects the LED and the pin if a resistor is missing.
  // With a proper 220-330 Ω resistor you can delete this line for full brightness.
  gpio_set_drive_capability(static_cast<gpio_num_t>(PIN_LED), GPIO_DRIVE_CAP_0);

  rgbLedWrite(PIN_RGB, 0, 0, 0);  // Switch off the on-board LED from lesson 01.
  log_i("LED on GPIO %d ready.", PIN_LED);
  setMode(Mode::Fade);
  printHelp();
}

void loop() {
  pollSerial();
  ledcWrite(PIN_LED, dutyFor(millis() - state.modeStartedAt));
  delay(5);
}

// The one place that says which wire goes where.
// Change a number here (or pass -DPIN_xxx=N as a build flag) and every lesson follows.
//
// Pins to keep away from on the ESP32-S3-N16R8:
//   0, 3, 45, 46   strapping pins: they decide how the chip boots
//   19, 20         native USB D- / D+
//   26-32          wired to the flash chip
//   33-37          wired to the octal PSRAM (that's the "R8" in N16R8)
//   43, 44         UART0 TX / RX: the serial monitor on the "COM" port
#pragma once

// On-board addressable RGB LED (WS2812). Most N16R8 DevKitC clones use 48;
// v1.1 boards use 38. If lesson 01 shows no colour, try 38.
#ifndef PIN_RGB
#define PIN_RGB 48
#endif

// The BOOT button already on the board. It only matters at power-on (hold it to enter flash mode);
// once our program runs, GPIO 0 is a normal input. Pressed = LOW. Used from lesson 03b.
#ifndef PIN_BOOT_BTN
#define PIN_BOOT_BTN 0
#endif

// Lesson 03b: external push button. GPIO 5 -> one leg, the diagonally opposite leg -> GND.
// The internal pull-up makes the pin read HIGH when up and LOW when pressed.
#ifndef PIN_BUTTON
#define PIN_BUTTON 5
#endif

// Lesson 02: external LED. GPIO 4 -> 220-330 ohm resistor -> LED long leg (+), short leg (-) -> GND.
#ifndef PIN_LED
#define PIN_LED 4
#endif

// Lesson 03: 1.9" ST7789 SPI display. These are the S3's native SPI2 (FSPI) pins, the fastest route.
// Module label -> ESP32-S3 pin
#ifndef PIN_TFT_SCLK
#define PIN_TFT_SCLK 12  // SCL / SCK / CLK
#endif
#ifndef PIN_TFT_MOSI
#define PIN_TFT_MOSI 11  // SDA / MOSI / DIN
#endif
#ifndef PIN_TFT_CS
#define PIN_TFT_CS 10    // CS
#endif
#ifndef PIN_TFT_DC
#define PIN_TFT_DC 9     // DC / RS / A0
#endif
#ifndef PIN_TFT_RST
#define PIN_TFT_RST 8    // RES / RST
#endif
#ifndef PIN_TFT_BL
#define PIN_TFT_BL 7     // BLK / BL / LED (backlight)
#endif

// RFID track: the RC522 board (MFRC522 chip) on the S3's second SPI bus (SPI3), so it never shares
// wires or timing with the screen on SPI2. The four SPI pins sit side by side on the left header
// in the same order as the module's pins: SDA, SCK, MOSI, MISO.
// Module label -> ESP32-S3 pin. 3.3V only: the MFRC522 is not 5 V tolerant.
#ifndef PIN_RFID_SS
#define PIN_RFID_SS 15    // SDA (in SPI mode this is chip select, NSS)
#endif
#ifndef PIN_RFID_SCK
#define PIN_RFID_SCK 16   // SCK
#endif
#ifndef PIN_RFID_MOSI
#define PIN_RFID_MOSI 17  // MOSI
#endif
#ifndef PIN_RFID_MISO
#define PIN_RFID_MISO 18  // MISO
#endif
#ifndef PIN_RFID_RST
#define PIN_RFID_RST 14   // RST (low = hard power-down)
#endif
#ifndef PIN_RFID_IRQ
#define PIN_RFID_IRQ 13   // IRQ (optional: -1 = not wired, the lab then polls)
#endif

// Sound track: the KY-037 microphone module (electret capsule + LM393 comparator + a blue trim pot).
// Power it from 3V3, never 5 V: its AO and DO outputs swing up to its supply, and the ESP32-S3 pins
// take 3.3 V at most. Module label -> ESP32-S3 pin.
//   AO must be an ADC1 pin (GPIO 1-10): ADC2 is busy while Wi-Fi is on. 6 = ADC1 channel 5.
//   DO is the comparator's yes/no output: any digital pin.
#ifndef PIN_MIC_AO
#define PIN_MIC_AO 6   // AO (analog: the microphone's voltage)
#endif
#ifndef PIN_MIC_DO
#define PIN_MIC_DO 21  // DO (digital: high = louder than the pot's threshold)
#endif

// Sound track, digital: the INMP441 MEMS microphone (I2S, 24-bit). VDD -> 3V3, GND -> GND,
// L/R -> GND (we read the left slot). Three wires in a row on the right header.
#ifndef PIN_I2S_MIC_SCK
#define PIN_I2S_MIC_SCK 40  // SCK (bit clock)
#endif
#ifndef PIN_I2S_MIC_WS
#define PIN_I2S_MIC_WS 41   // WS (word select: left/right)
#endif
#ifndef PIN_I2S_MIC_SD
#define PIN_I2S_MIC_SD 42   // SD (the data)
#endif

// Sound track, out loud: the MAX98357A I2S amplifier + a 4 ohm speaker on its screw terminal.
// VIN -> 5V (louder; 3V3 works, quieter), GND -> GND, GAIN and SD unconnected (9 dB, mono mix).
#ifndef PIN_I2S_SPK_BCLK
#define PIN_I2S_SPK_BCLK 39  // BCLK
#endif
#ifndef PIN_I2S_SPK_LRC
#define PIN_I2S_SPK_LRC 38   // LRC (word select)
#endif
#ifndef PIN_I2S_SPK_DIN
#define PIN_I2S_SPK_DIN 47   // DIN (the data)
#endif
